export const inputActionNames={jump:'Jump',slide:'Slide',tag:'Tag nearby player',addvariable:'Add to counter',setvariable:'Set counter',sound:'Play sound',hide:'Hide object',show:'Show object'};
export function matchingInputEvents(project,trigger,code){return(project.inputEvents||[]).filter(e=>e.trigger===trigger&&e.code===code)}
export function renderInputEvents(el,project,onChange){project.inputEvents??=[];const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));el.innerHTML='<h3>Buttons & keys</h3>'+project.inputEvents.map((e,i)=>`<div class="input-event-row"><label>When<select data-rule="${i}" data-field="trigger"><option value="key" ${e.trigger==='key'?'selected':''}>Key pressed</option><option value="mouse" ${e.trigger==='mouse'?'selected':''}>Mouse clicked</option></select></label>${e.trigger==='key'?`<label>Key<input data-capture="${i}" value="${escape(e.code.replace(/^Key/,''))}" readonly aria-label="Key for event ${i+1}" title="Click, then press a key"></label>`:`<label>Button<select data-rule="${i}" data-field="code">${[['Mouse0','Left click'],['Mouse2','Right click'],['Mouse1','Middle click']].map(([v,label])=>`<option value="${v}" ${e.code===v?'selected':''}>${label}</option>`).join('')}</select></label>`}<label>Do this<select data-rule="${i}" data-field="action">${Object.entries(inputActionNames).map(([v,label])=>`<option value="${v}" ${e.action===v?'selected':''}>${label}</option>`).join('')}</select></label>${['addvariable','setvariable'].includes(e.action)?`<label>Counter<select data-rule="${i}" data-field="variable">${Object.keys(project.variables||{}).map(v=>`<option ${v===(e.variable||'Score')?'selected':''}>${escape(v)}</option>`).join('')}</select></label><label>Amount<input type="number" data-rule="${i}" data-field="value" value="${e.value??1}"></label>`:e.action==='sound'?`<label>Sound<select data-rule="${i}" data-field="soundId">${(project.sounds||[]).map(s=>`<option value="${escape(s.id)}" ${s.id===e.soundId?'selected':''}>${escape(s.name)}</option>`).join('')}</select></label>`:['hide','show'].includes(e.action)?`<label>Object<select data-rule="${i}" data-field="targetId">${project.objects.map(o=>`<option value="${escape(o.id)}" ${o.id===e.targetId?'selected':''}>${escape(o.name)}</option>`).join('')}</select></label>`:''}<button data-remove-input="${i}">Remove event</button></div>`).join('')+'<button id="add-input-event">+ Input event</button>';el.querySelectorAll('[data-rule]').forEach(input=>input.onchange=()=>{const e=project.inputEvents[+input.dataset.rule],field=input.dataset.field;e[field]=field==='value'?Math.max(-1e6,Math.min(1e6,Number(input.value)||0)):input.value;if(field==='trigger')e.code=e.trigger==='mouse'?'Mouse0':'KeyE';if(e.action==='sound')e.soundId??=project.sounds?.[0]?.id;if(['show','hide'].includes(e.action))e.targetId??=project.objects[0]?.id;onChange();renderInputEvents(el,project,onChange)});el.querySelectorAll('[data-capture]').forEach(input=>{input.onfocus=()=>input.value='Press a key…';input.onkeydown=e=>{e.preventDefault();e.stopPropagation();project.inputEvents[+input.dataset.capture].code=e.code;onChange();renderInputEvents(el,project,onChange)}});el.querySelectorAll('[data-remove-input]').forEach(b=>b.onclick=()=>{project.inputEvents.splice(+b.dataset.removeInput,1);onChange();renderInputEvents(el,project,onChange)});el.querySelector('#add-input-event').onclick=()=>{if(project.inputEvents.length>=50)return;project.inputEvents.push({id:crypto.randomUUID(),trigger:'key',code:'KeyE',action:'tag',value:1});onChange();renderInputEvents(el,project,onChange)}}
